mapper.select:

where r.del_flag = '0'

	AND r.role_id = #{query.roleId}


	AND r.role_name like concat('%', #{query.roleName}, '%')


	AND r.status = #{query.status}


	AND r.role_key like concat('%', #{query.roleKey}, '%')


	and date_format(r.create_time,'%Y%m%d') >= date_format(#{query.params.beginTime},'%Y%m%d')


	and date_format(r.create_time,'%Y%m%d') <= date_format(#{query.params.endTime},'%Y%m%d')


${query.params.dataScopeQuery}
order by r.role_sort
